const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,day=()=>dateKey(),fromKey=s=>new Date(s+'T12:00:00'),shift=(s,n)=>{let d=fromKey(s);d.setDate(d.getDate()+n);return dateKey(d)},weekStart=s=>{let d=fromKey(s);d.setDate(d.getDate()-(d.getDay()+6)%7);return dateKey(d)},weekday=s=>(fromKey(s).getDay()+6)%7;
const seed=()=>({version:3,tasks:[{id:id(),name:'30 perc olvasás',emoji:'📚',points:20,kind:'habit',frequency:'daily',days:[],created:day(),category:'Tanulás',weekdays:[0,1,2,3,4,5,6],weeklyTarget:3,subtasks:[],paused:[]},{id:id(),name:'Porszívózás',emoji:'🧹',points:10,kind:'todo',frequency:'once',days:[],created:day(),category:'Otthon',subtasks:[],paused:[]},{id:id(),name:'30 perc mozgás',emoji:'🏃',points:30,kind:'habit',frequency:'weekly',weeklyTarget:3,days:[],created:day(),category:'Egészség',subtasks:[],paused:[]},{id:id(),name:'Kifli tréning',emoji:'🐶',points:20,kind:'habit',frequency:'daily',days:[],created:day(),category:'Egyéb',subtasks:[],paused:[]}],rewards:[{id:id(),name:'Nintendo Switch – 30 perc',emoji:'🎮',cost:100},{id:id(),name:'Dragon Ball kártyacsomag',emoji:'🎴',cost:250}],ledger:[],history:[],settings:{reminder:'20:00',reminderEnabled:false},focusSessions:[],questClaims:[],subtaskChecks:{},wishId:null,categories:['Munka','Otthon','Egészség','Tanulás','Egyéb'],progressLogs:[],activeRewards:[],weeklyChallenges:[],ui:{blocks:['level','progress','tasks','quests','wish'],hidden:[]}});
