function modal(html){$('#modalRoot').innerHTML=`<div class="modal"><div class="sheet">${html}</div></div>`}function close(){$('#modalRoot').replaceChildren()}
function taskModal(t){let days=t?.weekdays||[0,1,2,3,4,5,6];modal(`<h2>${t?'Feladat szerkesztése':'Új feladat'}</h2><form id="taskForm"><div class="field"><label>Név</label><input name="name" required maxlength="90" value="${esc(t?.name||'')}"></div><div class="field"><label>Emoji</label>${emojiPicker(t?.emoji||'✨')}</div><div class="field"><label for="subtaskEditor">Részfeladatok</label><textarea id="subtaskEditor" name="subtasks" rows="3" maxlength="6000" placeholder="Minden lépés külön sorba">${esc((t?.subtasks||[]).join('\n'))}</textarea><small class="muted">Soronként egy lépés, legfeljebb 50. Nem jár értük külön XP.</small></div><div class="field"><label>XP érték</label><input name="points" type="number" min="1" max="1000" required value="${t?.points||20}"></div><div class="field"><label>Kategória</label><select name="category">${state.categories.map(c=>`<option ${t?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Prioritás</label><select name="priority">${[['low','Low – alacsony'],['medium','Medium – közepes'],['high','High – magas']].map(([v,l])=>`<option value="${v}" ${(t?.priority||'medium')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Típus</label><select name="kind"><option value="habit" ${t?.kind==='habit'?'selected':''}>Szokás</option><option value="todo" ${t?.kind==='todo'?'selected':''}>Egyszeri teendő</option></select></div><div class="field" data-only="todo"><label>Feladat napja</label><input type="date" name="dueDate" value="${esc(t?.dueDate||(!t?selectedDate:t.created||day()))}"></div><div class="field" data-only="habit"><label>Ismétlődés</label><select name="frequency"><option value="daily" ${t?.frequency==='daily'?'selected':''}>Minden nap</option><option value="weekdays" ${t?.frequency==='weekdays'?'selected':''}>Kijelölt napokon</option><option value="weekly" ${t?.frequency==='weekly'?'selected':''}>Heti X alkalommal</option></select></div><div class="field" data-frequency="weekdays"><label>Napok (H–V)</label><div class="daychecks">${['H','K','Sze','Cs','P','Szo','V'].map((d,i)=>`<label><input type="checkbox" name="weekday" value="${i}" ${days.includes(i)?'checked':''}>${d}</label>`).join('')}</div></div><div class="field" data-frequency="weekly"><label>Heti cél (1–7)</label><input type="number" name="weeklyTarget" min="1" max="7" value="${t?.weeklyTarget||3}"></div><div class="field" data-only="habit"><label>Időszakos cél (opcionális)</label><select name="goalPeriod"><option value="">Nincs</option><option value="week" ${t?.goal?.period==='week'?'selected':''}>Heti</option><option value="month" ${t?.goal?.period==='month'?'selected':''}>Havi</option></select><input type="number" name="goalTarget" min="1" step="0.1" placeholder="Célmennyiség" value="${t?.goal?.target||''}"><input name="goalUnit" maxlength="18" placeholder="Egység, pl. km, perc" value="${esc(t?.goal?.unit||'')}"></div><div class="actions"><button class="btn" type="submit">Mentés</button><button class="btn alt" type="button" data-action="close">Mégse</button>${t?.kind==='habit'?`<button class="btn alt" type="button" data-action="${t.archived?'restoreTask':'archiveTask'}" data-id="${esc(t.id)}">${t.archived?'Visszaállítás':'Archiválás'}</button>${!t.archived?`<button class="btn alt" type="button" data-workflow-action="pausePlan" data-id="${esc(t.id)}">Tervezett szünet</button>`:''}`:''}${t?`<button class="btn danger" type="button" data-action="deleteTask" data-id="${esc(t.id)}">Törlés</button>`:''}</div></form>`);const form=$('#taskForm');const syncFields=()=>{const kind=form.elements.kind.value,frequency=form.elements.frequency.value;form.querySelectorAll('[data-only]').forEach(el=>el.hidden=el.dataset.only!==kind);form.querySelectorAll('[data-frequency]').forEach(el=>el.hidden=kind!=='habit'||el.dataset.frequency!==frequency)};form.elements.kind.addEventListener('change',syncFields);form.elements.frequency.addEventListener('change',syncFields);syncFields();$('#taskForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),p=Number(f.get('points')),w=Number(f.get('weeklyTarget'));if(!Number.isInteger(p)||p<1||p>1000||(f.get('kind')==='habit'&&f.get('frequency')==='weekly'&&(!Number.isInteger(w)||w<1||w>7)))return toast('Ellenőrizd a XPértéket és a heti célt.');const subtasks=String(f.get('subtasks')||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(subtasks.length>50||subtasks.some(x=>x.length>120))return toast('Legfeljebb 50 részfeladatot adj meg, lépésenként legfeljebb 120 karakterrel.');let item={...t,id:t?.id||id(),name:String(f.get('name')).trim(),emoji:String(f.get('emoji')).trim()||'✨',points:p,kind:f.get('kind'),frequency:f.get('kind')==='todo'?'once':f.get('frequency'),category:f.get('category'),priority:f.get('priority'),weekdays:f.getAll('weekday').map(Number),weeklyTarget:w,subtasks,days:t?.days||[],paused:t?.paused||[],created:t?.created||selectedDate,dueDate:String(f.get('dueDate')||selectedDate),order:t?.order||0,goal:f.get('kind')==='habit'&&f.get('goalPeriod')&&Number(f.get('goalTarget'))>0?{period:f.get('goalPeriod'),target:Number(f.get('goalTarget')),unit:String(f.get('goalUnit')||'alkalom').trim()}:null};if(!item.name||(item.kind==='habit'&&item.frequency==='weekdays'&&!item.weekdays.length))return toast('Adj meg nevet és legalább egy napot.');if(item.kind==='todo'){if(t?.kind==='todo'&&t.days.length)item.dueDate=t.dueDate||t.created;if(item.created>item.dueDate)item.created=item.dueDate}const next=JSON.parse(JSON.stringify(state));next.tasks=t?next.tasks.map(x=>x.id===t.id?item:x):[...next.tasks,item];if(t)Object.keys(next.subtaskChecks).filter(k=>k.startsWith(t.id+':')).forEach(k=>{next.subtaskChecks[k]=remapSubtasks(t.subtasks,subtasks,next.subtaskChecks[k])});if(!replaceState(next))return;close();render();toast('Feladat mentve')}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-emoji]');if(!b)return;const form=b.closest('form');if(!form)return;form.querySelector('[name=emoji]').value=b.dataset.emoji;const picker=b.closest('.emoji-picker');picker.querySelector('.selected-emoji').textContent=b.dataset.emoji;picker.querySelector('.emoji-grid').hidden=true;const trigger=picker.querySelector('.emoji-picker-toggle');trigger.setAttribute('aria-expanded','false');trigger.focus();form.querySelectorAll('[data-emoji]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b))})});
function rewardModal(r){modal(`<h2>${r?'Jutalom szerkesztése':'Új jutalom'}</h2><form id="rewardForm"><div class="field"><label>Név</label><input name="name" required maxlength="90" value="${esc(r?.name||'')}"></div><div class="field"><label>Emoji</label>${emojiPicker(r?.emoji||'🎁')}</div><div class="field"><label>Ár (pont)</label><input name="cost" type="number" min="1" max="100000" required value="${r?.cost||100}"></div><div class="field"><label>Időkorlát percben (0 = nincs)</label><input name="minutes" type="number" min="0" max="1440" value="${r?.minutes||0}"></div><div class="actions"><button class="btn" type="submit">Mentés</button><button class="btn alt" type="button" data-action="close">Mégse</button>${r?`<button class="btn danger" type="button" data-action="deleteReward" data-id="${esc(r.id)}">Törlés</button>`:''}</div></form>`);$('#rewardForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),cost=Number(f.get('cost'));if(!Number.isInteger(cost)||cost<1||cost>100000)return toast('Hibás ár');let item={id:r?.id||id(),name:String(f.get('name')).trim(),emoji:String(f.get('emoji')).trim()||'🎁',cost,minutes:Math.max(0,Math.min(1440,Number(f.get('minutes'))||0))};if(!item.name)return;state.rewards=r?state.rewards.map(x=>x.id===r.id?item:x):[...state.rewards,item];save();close();render()}}
function toggle(t){let d=selectedDate;if(t.archived)return toast('Előbb állítsd vissza az archivált szokást.');if(d>day())return toast('Jövőbeli feladatot még nem teljesíthetsz.');let done=isDone(t,d),before=level(),old=achievements().filter(a=>a.ok).map(a=>a.name);if(isPaused(t,d)&&!done)return toast('Ez a szokás ma szünetel.');if(!done&&!scheduled(t,d))return toast('Ez a feladat ma nem esedékes.');if(done){let index=state.history.findIndex(h=>h.type==='task'&&h.taskId===t.id&&(t.kind==='todo'||h.date===d));if(index<0)return toast('Nem vonható vissza');let h=state.history[index];state.history.splice(index,1);t.days=t.kind==='todo'?[]:t.days.filter(x=>x!==d);if(!h.xpReset)state.ledger.push({id:id(),amount:-h.points,type:'reversal',date:d})}else{t.days.push(d);state.ledger.push({id:id(),amount:t.points,type:'task',date:d});state.history.push({id:id(),type:'task',taskId:t.id,name:t.name,points:t.points,date:d})}save();render();if(!done){celebrate(t.points,level()>before?`🎉 LEVEL UP! ${level()}. szint`:achievements().some(a=>a.ok&&!old.includes(a.name))?'🏅 Új achievement!':'Küldetés teljesítve!')}else toast('Teljesítés visszavonva')}
function claim(k){let q=quests().find(q=>q.key===k);if(!q||q.progress<q.target||state.questClaims.includes(k))return;state.questClaims.push(k);state.ledger.push({id:id(),amount:q.points,type:'quest',date:day()});state.history.push({id:id(),type:'quest',name:q.name,points:q.points,date:day()});save();render();celebrate(q.points,'Küldetésbónusz!')}
const fmtTime=n=>`${String(Math.floor(Math.max(0,n)/60)).padStart(2,'0')}:${String(Math.max(0,n)%60).padStart(2,'0')}`;
function remind(){if(!state.settings.reminderEnabled)return;let now=new Date(),hhmm=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,stamp='levelup-reminder-'+day();if(hhmm===state.settings.reminder&&sessionStorage.getItem(stamp)!=='1'){sessionStorage.setItem(stamp,'1');toast('🌙 Esti LevelUp ellenőrzés!');if('Notification'in window&&Notification.permission==='granted')new Notification('LevelUp – esti emlékeztető',{body:'Nézd meg a mai küldetéseidet!'});}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,k=b.dataset.id,t=state.tasks.find(x=>x.id===k),r=state.rewards.find(x=>x.id===k);if(a==='habitCalendar'&&t){habitCalendarModal(t,b.dataset.month||day().slice(0,7));return}if(a==='challengeClaim'){const c=state.weeklyChallenges.find(x=>x.id===k),w=weekStart(day()),t=state.tasks.find(x=>x.id===c?.taskId);if(c&&t&&t.days.filter(d=>d>=w&&d<=shift(w,6)).length>=c.target&&!(c.claimed||[]).includes(w)){c.claimed=[...(c.claimed||[]),w];state.ledger.push({id:id(),amount:c.bonus,type:'challenge',date:day()});state.history.push({id:id(),type:'challenge',name:'Heti kihívás: '+t.name,points:c.bonus,date:day()});save();render();celebrate(c.bonus,'Heti kihívás teljesítve!')}return}if(a==='challengeDelete'){if(confirm('Törlöd ezt a heti kihívást?')){state.weeklyChallenges=state.weeklyChallenges.filter(c=>c.id!==k);save();render()}return}if(a==='xpDetail'){xpDetailModal();return}if(a==='carry'&&t){rescheduleTodos([t.id],day());return}
if(a==='carryAll'){rescheduleTodos(state.tasks.filter(x=>x.kind==='todo'&&!x.days.length&&(x.dueDate||x.created)<day()).map(x=>x.id),day());return}
if(a==='move'&&t){const peers=sortedTasks(state.tasks.filter(x=>x.category===t.category&&x.priority===t.priority&&scheduled(x,selectedDate)));const at=peers.findIndex(x=>x.id===t.id),next=peers[at+Number(b.dataset.dir)];if(next){const base=peers.map((x,i)=>({...x,order:i*10}));const a=base.find(x=>x.id===t.id),z=base.find(x=>x.id===next.id);[a.order,z.order]=[z.order,a.order];base.forEach(x=>{state.tasks.find(y=>y.id===x.id).order=x.order});save();render()}return}
if(a==='goalAdd'&&t?.goal){const input=prompt(`Mennyi ${t.goal.unit} teljesült?`,'1');if(input===null)return;const val=Number(input.replace(',','.'));if(!Number.isFinite(val)||val<=0||val>100000)return toast('Érvénytelen mennyiség');state.progressLogs.push({id:id(),taskId:t.id,date:day(),value:val});save();render();return}
if(a==='blockMove'){let i=state.ui.blocks.indexOf(k),j=i+Number(b.dataset.dir);if(j>=0&&j<state.ui.blocks.length){[state.ui.blocks[i],state.ui.blocks[j]]=[state.ui.blocks[j],state.ui.blocks[i]];save();render()}return}
if(a==='deleteCategory'){const c=b.dataset.category;if(state.tasks.some(t=>t.category===c))return toast('A kategóriában még vannak feladatok');state.categories=state.categories.filter(x=>x!==c);save();render();return}
if(a==='resetXP'){resetXP()}else if(a==='highlightModal'){highlightModal()}else if(a==='setHighlight'&&t&&!t.archived&&scheduled(t,selectedDate)){const previous=state.dailyHighlights[selectedDate];state.dailyHighlights[selectedDate]=t.id;if(!save()){if(previous===undefined)delete state.dailyHighlights[selectedDate];else state.dailyHighlights[selectedDate]=previous;return}close();render()}else if(a==='clearHighlight'){const previous=state.dailyHighlights[selectedDate];delete state.dailyHighlights[selectedDate];if(!save()){if(previous!==undefined)state.dailyHighlights[selectedDate]=previous;return}close();render()}else if(a==='archiveTask'&&t?.kind==='habit'){if(confirm('Archiválod ezt a szokást? Az előzmények és az XP megmaradnak.')){t.archived=true;if(!save()){t.archived=false;return}close();render();toast('Szokás archiválva')}}else if(a==='restoreTask'&&t?.kind==='habit'){t.archived=false;if(!save()){t.archived=true;return}close();render();toast('Szokás visszaállítva')}else if(a==='more'){moreModal()}else if(a==='tab'){tab=b.dataset.tab;close();render()}else if(a==='collapse'){let key=b.dataset.group;collapsedGroups.has(key)?collapsedGroups.delete(key):collapsedGroups.add(key);render()}else if(a==='dateSelect'){selectedDate=b.dataset.date;render()}else if(a==='dateShift'){selectedDate=shift(selectedDate,Number(b.dataset.offset));render()}else if(a==='dateToday'){selectedDate=day();render()}else if(a==='close')close();else if(a==='editTask')taskModal(t);else if(a==='editReward')rewardModal(r);else if(a==='toggle'&&t)toggle(t);else if(a==='claim')claim(k);else if(a==='subtasks'&&t)subtasksModal(t);else if(a==='pause'&&t){t.paused=isPaused(t)?t.paused.filter(x=>x!==day()):[...t.paused,day()];save();render()}else if(a==='wish'){state.wishId=state.wishId===k?null:k;save();render()}else if(a==='redeem'&&r&&wallet()>=r.cost&&confirm(`Beváltod: ${r.name} (${r.cost} XP)?`)){state.ledger.push({id:id(),amount:-r.cost,type:'reward',date:day()});state.history.push({id:id(),type:'reward',rewardId:r.id,name:r.name,points:r.cost,date:day()});if(r.minutes)state.activeRewards.push({id:id(),name:r.name,end:Date.now()+r.minutes*60000});save();render();toast('Jutalom beváltva!')}else if(a==='deleteTask'&&t){deleteEntity('task',t)}else if(a==='deleteReward'&&r){deleteEntity('reward',r)}else if(a==='focusDuration'){controlFocus('duration',Number(b.dataset.min))}else if(a==='focusStart'){controlFocus('toggle')}else if(a==='focusReset'){controlFocus('reset')}else if(a==='saveReminder'){state.settings.reminder=$('#reminderTime').value;state.settings.reminderEnabled=$('#reminderEnabled').checked;save();syncPushSettings().catch(()=>{});toast('Emlékeztető mentve')}else if(a==='pushEnable')enablePush();else if(a==='pushDisable')disablePush();else if(a==='pushTest')testPush();else if(a==='notifyPermission'){if('Notification'in window&&Notification.requestPermission)Notification.requestPermission().then(p=>toast(p==='granted'?'Értesítés engedélyezve':'Az értesítés nincs engedélyezve'));else toast('Ez a böngésző nem támogatja az értesítést')}else if(a==='export'){let blob=new Blob([recoveryRequired?originalSave:JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`levelup-${recoveryRequired?'recovery':'backup'}-${day()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}else if(a==='import')$('#importFile')?.click();else if(a==='reset'&&confirm('Biztosan törlöd az összes adatodat?')){if(replaceWithCheckpoint(migrate(seed()),'Teljes törlés előtt'))render()}});
document.addEventListener('submit',e=>{if(e.target.id==='quickTaskForm'){
 e.preventDefault();const input=e.target.elements.name,name=input.value.trim();if(!name)return;
 const task={id:id(),name,emoji:'📝',points:10,kind:'todo',frequency:'once',category:state.categories.includes('Egyéb')?'Egyéb':state.categories[0]||'Egyéb',priority:'medium',created:selectedDate,dueDate:selectedDate,days:[],paused:[],subtasks:[],weekdays:[],weeklyTarget:1,order:0,goal:null,archived:false};
 state.tasks.push(task);if(!save()){state.tasks.pop();return}render();$('#quickTaskName')?.focus();toast('Teendő hozzáadva · 10 XP');return;
}if(e.target.id==='dailyGoalForm'){e.preventDefault();state.settings.dailyXPGoal=Math.max(1,Math.min(10000,Number(e.target.elements.dailyGoal.value)||100));save();render();return}if(e.target.id==='challengeForm'){e.preventDefault();const f=new FormData(e.target);const taskId=String(f.get('taskId'));if(!state.tasks.some(t=>t.id===taskId&&t.kind==='habit'))return toast('Válassz szokást');state.weeklyChallenges.push({id:id(),taskId,target:Math.max(1,Math.min(7,Number(f.get('target'))||4)),bonus:Math.max(1,Math.min(500,Number(f.get('bonus'))||50)),claimed:[]});save();render();return}if(e.target.id==='categoryForm'){e.preventDefault();const name=e.target.elements.category.value.trim();if(!name||state.categories.includes(name))return toast('Már létező vagy üres kategória');state.categories.push(name);save();render()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-planner-move]')){const t=state.tasks.find(t=>t.id===e.target.dataset.plannerMove);if(t&&e.target.value&&t.kind==='todo')rescheduleTodos([t.id],e.target.value);return}if(e.target.matches('[data-block-toggle]')){const k=e.target.dataset.blockToggle;state.ui.hidden=e.target.checked?state.ui.hidden.filter(x=>x!==k):[...new Set([...state.ui.hidden,k])];save();render()}});
document.addEventListener('change',async e=>{if(e.target.id!=='importFile')return;try{let file=e.target.files?.[0];if(!file)return;e.target.value='';let incoming=migrate(JSON.parse(await file.text()));if(!confirm('Az importálás felülírja a jelenlegi adataidat. Folytatod?'))return;if(!replaceWithCheckpoint(incoming,'Importálás előtt'))return;render();focusTick();toast('Mentés importálva')}catch{toast('Érvénytelen mentésfájl')}});
focus=normalizeFocus(state.focusTimer);save();render();focusTick();setInterval(()=>{focusTick();remind();document.querySelectorAll('[data-timer]').forEach(el=>{const r=state.activeRewards.find(x=>x.id===el.dataset.timer);if(r)el.textContent=fmtTime(Math.ceil(Math.max(0,r.end-Date.now())/1000))})},1000);if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});

// Real background Web Push: requires an independently deployed HTTPS push service.
function pushURL(){return (state.settings.pushServer||'').replace(/\/+$/,'')}
function urlBase64ToUint8Array(base64){const padding='='.repeat((4-base64.length%4)%4),raw=atob((base64+padding).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function pushRequest(path,body){const res=await fetch(pushURL()+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!res.ok)throw Error('Push szerver hiba: '+res.status);return res.json()}
async function pushSubscription(){const reg=await navigator.serviceWorker.ready;return reg.pushManager.getSubscription()}
async function syncPushSettings(){if(!pushURL())return;const sub=await pushSubscription();if(sub)await pushRequest('/api/subscribe',{subscription:sub.toJSON(),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,reminder:state.settings.reminder,enabled:state.settings.reminderEnabled})}
async function enablePush(){try{const input=$('#pushServer');if(input)state.settings.pushServer=input.value.trim().replace(/\/+$/,'');if(!/^https:\/\//.test(pushURL()))throw Error('Adj meg egy működő HTTPS push szerver címet.');if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('A készülék nem támogatja a Web Push funkciót. iPhone-on telepítsd a PWA-t a főképernyőre (iOS 16.4+).');const perm=await Notification.requestPermission();if(perm!=='granted')throw Error('Az értesítések engedélyezése szükséges.');const reg=await navigator.serviceWorker.ready;const keyResponse=await fetch(pushURL()+'/api/public-key');if(!keyResponse.ok)throw Error('A push szerver nem érhető el.');const {publicKey}=await keyResponse.json();let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(publicKey)});await pushRequest('/api/subscribe',{subscription:sub.toJSON(),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,reminder:state.settings.reminder,enabled:true});state.settings.reminderEnabled=true;save();render();toast('Háttér push engedélyezve!')}catch(err){toast(err.message||'Nem sikerült a push bekapcsolása')}}
async function disablePush(){try{const sub=await pushSubscription();if(sub){if(pushURL())await pushRequest('/api/unsubscribe',{endpoint:sub.endpoint});await sub.unsubscribe()}state.settings.reminderEnabled=false;save();render();toast('Push kikapcsolva')}catch(e){toast('Nem sikerült: '+e.message)}}
async function testPush(){try{const sub=await pushSubscription();if(!sub||!pushURL())throw Error('Előbb kapcsold be a háttér push-t.');await pushRequest('/api/test',{endpoint:sub.endpoint});toast('Teszt push elküldve')}catch(e){toast(e.message)}}
